-- SUPPORTERS' MOBILE-MONEY PAYMENTS BOOKED AS AGENT FLOAT — batch acct_corr_202611_momo_supporter. DRAFT, not approved.
--
-- ACCOUNTING RECORDS ONLY. NO MONEY MOVEMENT. Platform-scope journals only: no wallet leg; no wallet, deposit,
-- portfolio, Returns or payout change; nothing is deleted.
--
-- Evidence (read-only, 10 Nov 2026; confidential workbook sheets F*): each listed deposit is a mobile-money payment
-- auto-created and auto-approved from an SMS/email receipt (linked in gmail_transactions) and routed to the payer's
-- FLOAT bucket by the float-by-default rule. It was booked DR A2 agent float / CR A8 float cycle control, and never
-- reached A1, although the money was received on the company's mobile-money line. The float-origin trace shows the
-- listed amount of each deposit then paid for the SAME person's portfolio (DR L1 / CR L2).
-- Correct record: money received and held for the Supporter until the portfolio is funded (agreed context A).
--
-- Per deposit, amount X = the part of the deposit that funded the payer's own portfolio (one balanced group):
--   DR A1 verified_bank_cash_recognised (cash_in)   - money received on the company's mobile-money line
--   DR A8 agent_float_deposit           (cash_in)   - reverses the float-cycle credit
--   CR L1 cash_custody_payable          (cash_out)  - held for the Supporter; closed by the existing DR L1 portfolio leg
--   CR A2 agent_float_cash_offset       (cash_out)  - reverses the agent-float debit (the money was never with an agent)
-- Net with the portfolio leg: DR A1 / CR L2.
--
-- 648 deposits, UGX 606,941,585 (excluded: 3 already booked to A1 and 1 without a linked receipt, 223,302; 3 since marked
-- reversed, 1,600,000).
-- Rollback: the same groups with directions swapped (see the end of this file).
begin;

create temp table _s (deposit_id uuid primary key, amount numeric not null, orig_group uuid not null) on commit drop;
;
create temp table _expected (n int not null, amount numeric not null) on commit drop;
-- transaction date of each correction: 'original' (the deposit's own date) or a timestamp
create temp table _params (key text primary key, value text not null) on commit drop;

do $corr$
declare
  c_batch constant text := 'acct_corr_202611_momo_supporter';
  c_cfo   constant uuid := '29a0cfa8-1eaf-453c-874c-0fc72fa4f74b';
  r record; e record; v_n int; v_x numeric; v_grp uuid; v_td timestamptz; v_mode text;
  s_wallet_legs bigint; s_wallet_sum numeric; s_dep text; s_pf text;
begin
  if exists (select 1 from public.accounting_correction_register where batch = c_batch) then
    raise exception 'STOP: batch % is already posted', c_batch;
  end if;
  select * into e from _expected;
  select count(*), coalesce(sum(amount), 0) into v_n, v_x from _s;
  if v_n <> e.n or v_x <> e.amount then raise exception 'STOP: input is % / %, approved % / %', v_n, v_x, e.n, e.amount; end if;
  v_mode := (select value from _params where key = 'transaction_date');

  -- 1. Every deposit must still be what the evidence describes.
  for r in
    select s.*, d.status, d.provider, d.amount dep_amount, d.transaction_id,
           exists (select 1 from public.gmail_transactions g where g.linked_deposit_request_id = s.deposit_id) email_linked,
           (select count(*) from public.general_ledger g where g.transaction_group_id = s.orig_group and g.source_id = s.deposit_id
              and g.ledger_scope = 'platform' and g.category = 'agent_float_deposit' and g.direction = 'cash_out' and g.amount = d.amount) orig_ok,
           (select count(*) from public.general_ledger g where g.transaction_group_id = s.orig_group and g.source_id = s.deposit_id
              and g.ledger_scope = 'wallet' and g.wallet_bucket = 'float' and g.category = 'agent_float_deposit' and g.direction = 'cash_in') wallet_ok
    from _s s left join public.deposit_requests d on d.id = s.deposit_id
  loop
    if r.status is distinct from 'approved' or r.provider not in ('airtel', 'mtn') or not r.email_linked
       or r.orig_ok <> 1 or r.wallet_ok <> 1 or r.amount <= 0 or r.amount > r.dep_amount then
      raise exception 'STOP: deposit % no longer matches the evidence (status %, provider %, receipt %, original %/%, amount % of %)',
        r.deposit_id, r.status, r.provider, r.email_linked, r.orig_ok, r.wallet_ok, r.amount, r.dep_amount;
    end if;
  end loop;

  -- 2. Money-safety snapshot.
  select count(*), coalesce(sum(amount), 0) into s_wallet_legs, s_wallet_sum from public.general_ledger where ledger_scope = 'wallet';
  select md5(coalesce(string_agg(t::text, '|' order by t.id), '')) into s_dep from public.deposit_requests t where t.id in (select deposit_id from _s);
  select md5(coalesce(string_agg(t::text, '|' order by t.id), '')) into s_pf from public.investor_portfolios t;

  -- 3. One balanced platform group per deposit.
  for r in select s.*, d.transaction_id, d.provider, g.transaction_date orig_date
           from _s s join public.deposit_requests d on d.id = s.deposit_id
           join lateral (select x.transaction_date from public.general_ledger x where x.transaction_group_id = s.orig_group limit 1) g on true
           order by g.transaction_date, s.deposit_id
  loop
    v_td := case when v_mode = 'original' then r.orig_date else v_mode::timestamptz end;
    v_grp := public.create_ledger_transaction(jsonb_build_array(
      jsonb_build_object('ledger_scope', 'platform', 'direction', 'cash_in', 'amount', r.amount, 'category', 'verified_bank_cash_recognised',
        'source_table', 'deposit_requests', 'source_id', r.deposit_id::text, 'reference_id', r.orig_group::text, 'currency', 'UGX',
        'transaction_date', v_td, 'classification', 'production',
        'description', format('Correction (accounting only, no money moved): Supporter''s %s payment %s (UGX %s used for their own portfolio) was received on the company''s mobile-money line; records it as cash.', r.provider, coalesce(r.transaction_id, r.deposit_id::text), r.amount)),
      jsonb_build_object('ledger_scope', 'platform', 'direction', 'cash_in', 'amount', r.amount, 'category', 'agent_float_deposit',
        'source_table', 'deposit_requests', 'source_id', r.deposit_id::text, 'reference_id', r.orig_group::text, 'currency', 'UGX',
        'transaction_date', v_td, 'classification', 'production',
        'description', format('Correction (accounting only, no money moved): reverses the float-cycle credit booked for %s payment %s, which was the Supporter''s own money, not agent float.', r.provider, coalesce(r.transaction_id, r.deposit_id::text))),
      jsonb_build_object('ledger_scope', 'platform', 'direction', 'cash_out', 'amount', r.amount, 'category', 'cash_custody_payable',
        'source_table', 'deposit_requests', 'source_id', r.deposit_id::text, 'reference_id', r.orig_group::text, 'currency', 'UGX',
        'transaction_date', v_td, 'classification', 'production',
        'description', format('Correction (accounting only, no money moved): Supporter''s money held for them until it funded their portfolio (closed by the existing portfolio payment). Payment %s.', coalesce(r.transaction_id, r.deposit_id::text))),
      jsonb_build_object('ledger_scope', 'platform', 'direction', 'cash_out', 'amount', r.amount, 'category', 'agent_float_cash_offset',
        'source_table', 'deposit_requests', 'source_id', r.deposit_id::text, 'reference_id', r.orig_group::text, 'currency', 'UGX',
        'transaction_date', v_td, 'classification', 'production',
        'description', format('Correction (accounting only, no money moved): reverses the agent-float debit for payment %s; the money was received by the company, not held by an agent.', coalesce(r.transaction_id, r.deposit_id::text)))),
      idempotency_key := c_batch || ':' || r.deposit_id::text);
    values (v_grp, 'Reclassification of a mobile-money receipt already received (accounting only): not new money', 'M1');
      correction_group_id, amount, before_value, after_value, detail, created_by)
    values (c_batch, 'M1', 'momo_supporter_receipt_to_custody', 'deposit_requests', r.deposit_id, r.orig_group, v_grp, r.amount, r.amount, 0,
      jsonb_build_object('provider', r.provider, 'payment_reference', r.transaction_id, 'basis', 'float-origin trace: used for the payer''s own portfolio'), c_cfo);
  end loop;

  -- 4. Checks.
  select count(*), coalesce(sum(amount), 0) into v_n, v_x from public.accounting_correction_register where batch = c_batch;
  if v_n <> e.n or v_x <> e.amount then raise exception 'STOP: posted % / %', v_n, v_x; end if;
  if exists (select 1 from public.general_ledger g where g.idempotency_key like c_batch || ':%' and g.ledger_scope <> 'platform') then
    raise exception 'STOP: a correction leg is not platform-scope';
  end if;
  select count(*), coalesce(sum(amount), 0) into v_n, v_x from public.general_ledger where ledger_scope = 'wallet';
  if v_n <> s_wallet_legs or v_x <> s_wallet_sum then raise exception 'STOP: a wallet-scope ledger leg was written'; end if;
  if (select md5(coalesce(string_agg(t::text, '|' order by t.id), '')) from public.deposit_requests t where t.id in (select deposit_id from _s)) <> s_dep then
    raise exception 'STOP: a deposit record changed';
  end if;
  if (select md5(coalesce(string_agg(t::text, '|' order by t.id), '')) from public.investor_portfolios t) <> s_pf then
    raise exception 'STOP: a portfolio changed';
  end if;

  values (c_cfo, 'accounting_correction_batch_posted', 'momo_supporter_receipt_to_custody', 'accounting_correction_register', c_batch,
    'Supporters'' mobile-money payments booked as agent float, reclassified to cash held for the Supporter (accounting only)',
    jsonb_build_object('deposits', e.n, 'amount', e.amount, 'transaction_date', v_mode));
  raise notice 'batch % posted: % deposits, UGX %', c_batch, e.n, e.amount;
end $corr$;

commit;

-- ROLLBACK (only on CFO instruction): for each register row of this batch, post the same four legs with directions
-- swapped, idempotency key acct_corr_202611_momo_supporter:rb:<deposit id>, exclude from Money In, set rolled_back_at.
